#!/usr/bin/env python3
"""Multi-API LLM benchmark harness with streaming TTFT measurement."""

import argparse
import concurrent.futures
import datetime
import json
import os
import sys
import time
import uuid
import urllib.request
import urllib.error


PROMPT = "Reply with exactly one sentence about the color blue."


def build_request(model_cfg):
    api_type = model_cfg["api_type"]
    base_url = model_cfg["base_url"].rstrip("/")
    api_key = os.environ.get(model_cfg.get("api_key_env", ""), "")

    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
    }
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"

    if api_type == "chat_completions":
        url = f"{base_url}/v1/chat/completions"
        body = {
            "model": model_cfg["id"],
            "messages": [{"role": "user", "content": PROMPT}],
            "stream": True,
        }
    elif api_type == "responses":
        url = f"{base_url}/v1/responses"
        body = {
            "model": model_cfg["id"],
            "input": PROMPT,
            "stream": True,
        }
        # Anthropic-style auth fallback
        if api_key and "anthropic" in base_url:
            headers.pop("Authorization", None)
            headers["x-api-key"] = api_key
            headers["anthropic-version"] = "2023-06-01"
    else:
        raise ValueError(f"Unknown api_type: {api_type}")

    if "temperature" in model_cfg:
        body["temperature"] = model_cfg["temperature"]
    if "max_tokens" in model_cfg:
        if api_type == "chat_completions":
            body["max_tokens"] = model_cfg["max_tokens"]
        else:
            body["max_output_tokens"] = model_cfg["max_tokens"]

    data = json.dumps(body).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers, method="POST")
    return req


def extract_delta(api_type, payload):
    """Extract text delta from a parsed SSE JSON payload."""
    try:
        if api_type == "chat_completions":
            choices = payload.get("choices") or []
            if choices:
                delta = choices[0].get("delta") or {}
                return delta.get("content") or ""
        elif api_type == "responses":
            t = payload.get("type", "")
            if t == "content_block_delta":
                d = payload.get("delta") or {}
                return d.get("text") or ""
            if t == "response.output_text.delta":
                return payload.get("delta") or ""
    except Exception:
        return ""
    return ""


def benchmark_model(model_cfg, timeout):
    model_id = model_cfg.get("id", "<unknown>")
    api_type = model_cfg.get("api_type", "<unknown>")
    result = {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None,
    }

    try:
        req = build_request(model_cfg)
    except Exception as e:
        result["error"] = f"Request build failed: {e}"
        return result

    t_start = time.monotonic()
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            ttft = None
            first_token = None
            chunks = []
            for raw_line in resp:
                try:
                    line = raw_line.decode("utf-8", errors="replace").rstrip("\r\n")
                except Exception:
                    continue
                if not line or not line.startswith("data:"):
                    continue
                data_str = line[5:].lstrip()
                if data_str == "[DONE]":
                    break
                try:
                    payload = json.loads(data_str)
                except json.JSONDecodeError:
                    continue
                delta = extract_delta(api_type, payload)
                if delta:
                    if ttft is None:
                        ttft = (time.monotonic() - t_start) * 1000.0
                        first_token = delta
                    chunks.append(delta)
            total_ms = (time.monotonic() - t_start) * 1000.0
            result["total_ms"] = round(total_ms, 2)
            if ttft is not None:
                result["status"] = "ok"
                result["ttft_ms"] = round(ttft, 2)
                result["first_token"] = first_token
                result["full_response"] = "".join(chunks)
            else:
                result["error"] = "No content delta received"
    except urllib.error.HTTPError as e:
        result["total_ms"] = round((time.monotonic() - t_start) * 1000.0, 2)
        try:
            body = e.read().decode("utf-8", errors="replace")[:500]
        except Exception:
            body = ""
        result["error"] = f"HTTP {e.code}: {e.reason} {body}"
    except urllib.error.URLError as e:
        result["total_ms"] = round((time.monotonic() - t_start) * 1000.0, 2)
        result["error"] = f"URL error: {e.reason}"
    except TimeoutError:
        result["total_ms"] = round((time.monotonic() - t_start) * 1000.0, 2)
        result["error"] = f"Timeout after {timeout}s"
    except Exception as e:
        result["total_ms"] = round((time.monotonic() - t_start) * 1000.0, 2)
        result["error"] = f"{type(e).__name__}: {e}"

    return result


def summarize(results):
    ok = [r for r in results if r["status"] == "ok"]
    errors = [r for r in results if r["status"] != "ok"]
    summary = {
        "total": len(results),
        "ok": len(ok),
        "errors": len(errors),
        "avg_ttft_ms": None,
        "fastest_model": None,
        "slowest_model": None,
    }
    if ok:
        ttfts = [r["ttft_ms"] for r in ok]
        summary["avg_ttft_ms"] = round(sum(ttfts) / len(ttfts), 2)
        fastest = min(ok, key=lambda r: r["ttft_ms"])
        slowest = max(ok, key=lambda r: r["ttft_ms"])
        summary["fastest_model"] = fastest["model_id"]
        summary["slowest_model"] = slowest["model_id"]
    return summary


def main():
    parser = argparse.ArgumentParser(description="LLM benchmark harness with TTFT.")
    parser.add_argument("--config", required=True, help="Path to model config JSON.")
    parser.add_argument("--output", default="benchmark_results.json")
    parser.add_argument("--timeout", type=float, default=30.0)
    parser.add_argument("--workers", type=int, default=1)
    args = parser.parse_args()

    try:
        with open(args.config, "r", encoding="utf-8") as f:
            cfg = json.load(f)
    except Exception as e:
        print(f"Failed to load config: {e}", file=sys.stderr)
        sys.exit(1)

    models = cfg.get("models", [])
    if not models:
        print("No models in config.", file=sys.stderr)
        sys.exit(1)

    results = [None] * len(models)
    workers = max(1, args.workers)

    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as ex:
        future_to_idx = {
            ex.submit(benchmark_model, m, args.timeout): i for i, m in enumerate(models)
        }
        for fut in concurrent.futures.as_completed(future_to_idx):
            i = future_to_idx[fut]
            try:
                results[i] = fut.result()
            except Exception as e:
                results[i] = {
                    "model_id": models[i].get("id", "<unknown>"),
                    "api_type": models[i].get("api_type", "<unknown>"),
                    "status": "error",
                    "ttft_ms": None,
                    "total_ms": None,
                    "first_token": None,
                    "full_response": None,
                    "error": f"Worker crashed: {e}",
                }
            r = results[i]
            print(
                f"[{r['status']:5}] {r['model_id']:30} "
                f"ttft={r['ttft_ms']} ms total={r['total_ms']} ms"
                + (f"  err={r['error']}" if r['error'] else "")
            )

    output = {
        "run_id": str(uuid.uuid4()),
        "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "prompt": PROMPT,
        "results": results,
        "summary": summarize(results),
    }

    with open(args.output, "w", encoding="utf-8") as f:
        json.dump(output, f, indent=2)
    print(f"\nWrote {args.output}")


if __name__ == "__main__":
    main()
